    return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"

def is_valid_datetime_string(s):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    if len(s) != 19:
        return False
    date_part = s[0:10]
    sep = s[10]
    time_part = s[11:19]
    if sep != ' ':
        return False
    if date_part[4] != '-' or date_part[7] != '-':
        return False
    y_s, m_s, d_s = date_part[0:4], date_part[5:7], date_part[8:10]
    if not (y_s.isdigit() and m_s.isdigit() and d_s.isdigit()):
        return False
    y, m, d = int(y_s), int(m_s), int(d_s)
    if m < 1 or m > 12:
        return False
    dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if d < 1 or d > dim[m - 1]:
        return False
    if time_part[2] != ':' or time_part[5] != ':':
        return False
    hh_s, mm_s, ss_s = time_part[0:2], time_part[3:5], time_part[6:8]
    if not (hh_s.isdigit() and mm_s.isdigit() and ss_s.isdigit()):
        return False
    hh, mm, ss = int(hh_s), int(mm_s), int(ss_s)
    if hh < 0 or hh > 23:
        return False
    if mm < 0 or mm > 59:
        return False
    if ss < 0 or ss > 59:
        return False
    return True

