def fix_two_digit_year(s):
    yy, m, d = s.split('-')
    yy_int = int(yy)
    if yy_int <= 69:
        year = 2000 + yy_int
    else:
        year = 1900 + yy_int
    return f"{year}-{m}-{d}"

def count_valid_dates_in_list(date_list):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def is_valid(s):
        if len(s) != 10:
            return False
        if s[4] != '-' or s[7] != '-':
            return False
        y_s, m_s, d_s = s[0:4], s[5:7], s[8:10]
        if not (y_s.isdigit() and m_s.isdigit() and d_s.isdigit()):
            return False
        y, m, d = int(y_s), int(m_s), int(d_s)
        if m < 1 or m > 12:
            return False
        dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if d < 1 or d > dim[m - 1]:
            return False
        return True

    return sum(1 for s in date_list if is_valid(s))

