def convert_between_timezones(time_str, from_offset_min, to_offset_min):
    hh, mm = map(int, time_str.split(':'))
    total_minutes = hh * 60 + mm + (to_offset_min - from_offset_min)
    day_delta, rem = divmod(total_minutes, 1440)
    new_hour, new_minute = divmod(rem, 60)
    return (f"{new_hour:02d}:{new_minute:02d}", day_delta)

